CREATE OR REPLACE FUNCTION public.combat_v2_damage(p_state jsonb, p_target jsonb, p_amount numeric, p_opts jsonb DEFAULT NULL::jsonb, p_b jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
