  absorbed numeric := 0; hp_loss numeric := 0; hp numeric; woke boolean := false; st jsonb; mp jsonb; lim numeric; brood int; r jsonb;
  s jsonb; used jsonb := '[]'::jsonb; revived boolean := false;
